        assert_eq!(sender.send(7_u32), 2);
        assert_eq!(first.recv_timeout(Duration::from_millis(50)).unwrap(), 7);
        assert_eq!(second.recv_timeout(Duration::from_millis(50)).unwrap(), 7);
    }
